require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';$error='';finance_seed(shop_id());
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 switch($_POST['action']??''){
 case 'approve_journal':domain_require('accounting.approve');$lines=[];foreach($_POST['lines']??[] as $r){if(!is_array($r))throw new InvalidArgumentException('Invalid line.');if(dec_units($r['debit']??0)===0&&dec_units($r['credit']??0)===0)continue;$lines[]=[(string)($r['code']??''),$r['debit']??0,$r['credit']??0];}$key=(string)($_POST['request_key']??'');if(!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$key))throw new InvalidArgumentException('Invalid request.');$description=trim((string)($_POST['description']??''));if(mb_strlen($description)<3)throw new InvalidArgumentException('Enter a description.');finance_post('manual',$key,(string)($_POST['currency_code']??''),finance_date((string)($_POST['posting_date']??'')),$description,$lines);break;
 case 'approve_reversal':finance_reverse((int)($_POST['journal_id']??0),finance_date((string)($_POST['posting_date']??'')),(string)($_POST['reason']??''));break;
 case 'approve_purchase_opening':if(empty($_POST['inventory_opening_verified']))throw new InvalidArgumentException('Confirm the separate inventory opening review.');finance_review_purchase_opening((int)($_POST['purchase_id']??0),$_POST['verified_paid']??0,(string)($_POST['review_note']??''));break;
 case 'approve_period':finance_close_period((string)($_POST['closed_until']??''));break;
 default:throw new InvalidArgumentException('Unknown accounting action.');}redirect(BASE_URL.'modules/accounting.php');
}catch(Throwable $e){http_response_code(in_array($e->getCode(),[403,429],true)?$e->getCode():422);$error=public_error($e);}
$currency=currency_base_code();$through=$_GET['through']??date('Y-m-d');finance_date($through);$q=$pdo->prepare('SELECT a.code,a.name,a.account_type,COALESCE(SUM(CASE WHEN h.id IS NOT NULL THEN d.debit ELSE 0 END),0) AS debit,COALESCE(SUM(CASE WHEN h.id IS NOT NULL THEN d.credit ELSE 0 END),0) AS credit FROM ledger_accounts a LEFT JOIN journal_details d ON d.shop_id=a.shop_id AND d.account_code=a.code LEFT JOIN journal_headers h ON h.id=d.journal_id AND h.shop_id=d.shop_id AND h.currency_code=? AND h.posting_date<=? WHERE a.shop_id=? GROUP BY a.code,a.name,a.account_type ORDER BY a.code');$q->execute([$currency,$through,shop_id()]);$balances=$q->fetchAll();$q=$pdo->prepare('SELECT closed_until FROM financial_periods WHERE shop_id=?');$q->execute([shop_id()]);$closed=$q->fetchColumn();$sorts=['newest'=>['id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['id ASC','Oldest first','قدیمی‌ترین اول'],'date'=>['posting_date DESC,id DESC','Posting date','تاریخ ثبت']];[$list,$history]=listing_query($pdo,'SELECT * FROM journal_headers WHERE shop_id=? AND currency_code=? AND posting_date<=?',[shop_id(),$currency,$through],$sorts);$pageTitle=__t('Accounting books','دفاتر حسابداری','د حساب دفترونه');require __DIR__.'/../includes/header.php';
function account_label($a){if(preg_match('/^(PP|PR|PV)([0-9]+)$/D',$a['code'],$m))return ($m[1]==='PP'?__t('Partner principal','اصل سرمایهٔ شریک','د شریک اصلي پانګه'):($m[1]==='PR'?__t('Partner profit payable','مفاد قابل پرداخت شریک','د شریک پاتې ګټه'):__t('Partner profit recovery','طلب مفاد اضافه‌پرداخت‌شده','د اضافي ګټې طلب'))).' #'.$m[2];$chart=finance_chart();return isset($chart[$a['code']])?__t($chart[$a['code']][0],$chart[$a['code']][1],$chart[$a['code']][0]):$a['name'];}
?>
<h1><?= sanitize($pageTitle) ?></h1><p><?= __t('Each document balances in one currency. Historical business data is not silently recreated; verified opening balances are required before treating these books as complete.','هر سند در یک ارز تراز می‌شود. معلومات تاریخی به‌صورت حدسی بازسازی نمی‌شود؛ پیش از استفاده از دفاتر به‌عنوان حساب مکمل، مانده‌های آغاز باید تطبیق شوند.','هر سند په یوه اسعارو متوازن دی؛ لومړني مانده تایید کړئ.') ?></p><?php if($error):?><p role="alert" class="alert alert-danger"><?= sanitize($error) ?></p><?php endif ?>
<form method="get" class="card modern-form"><label><?= __t('Through date','تا تاریخ','تر نېټې') ?><input name="through" type="date" class="form-control" value="<?= sanitize($through) ?>"></label><button class="btn btn-primary"><?= __t('Show','نمایش','وښایئ') ?></button></form>
<section class="card modern-form table-responsive"><h2><?= __t('Trial balance','تراز آزمایشی','ازمایښتي بیلانس') ?> · <?= sanitize($currency) ?></h2><table class="table"><thead><tr><th><?= __t('Account','حساب','حساب') ?></th><th><?= __t('Debit balance','ماندهٔ بدهکار','ډېبېټ مانده') ?></th><th><?= __t('Credit balance','ماندهٔ بستانکار','کرېډېټ مانده') ?></th></tr></thead><tbody><?php $dr='0';$cr='0';$income='0';$expense='0';$assets='0';$liabilities='0';$equity='0';foreach($balances as $a):$net=dec_sub($a['debit'],$a['credit']);$debit=dec_units($net)>0?$net:'0.00';$credit=dec_units($net)<0?dec_mul($net,-1):'0.00';$dr=dec_add($dr,$debit);$cr=dec_add($cr,$credit);if($a['account_type']==='asset')$assets=dec_add($assets,$net);if($a['account_type']==='liability')$liabilities=dec_sub($liabilities,$net);if($a['account_type']==='equity')$equity=dec_sub($equity,$net);if($a['account_type']==='income')$income=dec_sub($income,$net);if($a['account_type']==='expense')$expense=dec_add($expense,$net);?><tr><td><?= sanitize($a['code'].' · '.account_label($a)) ?></td><td><?= sanitize($debit) ?></td><td><?= sanitize($credit) ?></td></tr><?php endforeach ?><tr><th><?= __t('Total','مجموع','ټول') ?></th><th><?= sanitize($dr) ?></th><th><?= sanitize($cr) ?></th></tr></tbody></table><p><?= __t('Net income after recorded costs','مفاد خالص پس از مصارف ثبت‌شده','له ثبت شوو لګښتونو وروسته ګټه') ?>: <?= sanitize(dec_sub($income,$expense).' '.$currency) ?></p><p><?= __t('Closed through','بسته‌شده تا','تړل شوی تر') ?>: <?= sanitize($closed?:'—') ?></p></section>
<section class="card modern-form"><h2><?= __t('Statement of financial position','صورت وضعیت مالی','د مالي وضعیت پاڼه') ?></h2><table class="table"><tbody><?php foreach([__t('Assets','دارایی‌ها','شتمنۍ')=>$assets,__t('Liabilities','بدهی‌ها','پورونه')=>$liabilities,__t('Equity before current profit','سرمایه پیش از مفاد فعلی','پانګه له اوسنۍ ګټې مخکې')=>$equity,__t('Current net profit','مفاد خالص فعلی','اوسنۍ خالصه ګټه')=>dec_sub($income,$expense)] as $label=>$amount):?><tr><th><?= $label ?></th><td><?= sanitize($amount.' '.$currency) ?></td></tr><?php endforeach ?></tbody></table><p><?= dec_units($assets)===dec_units(dec_add(dec_add($liabilities,$equity),dec_sub($income,$expense)))?__t('Assets equal liabilities plus equity and retained current profit.','دارایی‌ها با بدهی‌ها، سرمایه و مفاد فعلی برابر است.','شتمنۍ له پورونو، پانګې او ګټې سره برابرې دي.'):__t('Reconciliation required.','تطبیق حساب‌ها لازم است.','د حسابونو تطبیق اړین دی.') ?></p></section>
<section class="card modern-form"><details><summary><?= __t('Review a legacy purchase opening','بررسی ماندهٔ آغاز خرید قدیمی','د پخواني پېرود لومړنۍ مانده') ?></summary><p><?= __t('Verify historical payments independently. This opens only the remaining payable and does not create old cash movements. Review inventory and all other opening accounts separately before treating the books as complete.','پرداخت‌های تاریخی را مستقل تطبیق کنید. تنها بدهی باقی‌مانده ثبت می‌شود و پول تاریخی ساخته نمی‌شود. ماندهٔ آغاز موجودی و حساب‌های دیگر را جدا بررسی کنید تا دفاتر مکمل شوند.','تاریخي تادیات جلا تایید کړئ؛ یوازې پاتې پور پرانیستل کېږي.') ?></p><form method="post"><?= csrf_field() ?><input name="action" type="hidden" value="approve_purchase_opening"><label><?= __t('Legacy purchase','خرید قدیمی','پخوانی پېرود') ?><select class="form-control" name="purchase_id" required><?php $pq=$pdo->prepare("SELECT p.* FROM inventory_purchases p WHERE p.shop_id=? AND NOT EXISTS(SELECT 1 FROM journal_headers h WHERE h.shop_id=p.shop_id AND h.source_type='purchase' AND CAST(h.source_id AS SIGNED)=p.id) AND NOT EXISTS(SELECT 1 FROM purchase_opening_reviews o WHERE o.shop_id=p.shop_id AND o.purchase_id=p.id) ORDER BY p.id DESC LIMIT 250");$pq->execute([shop_id()]);foreach($pq->fetchAll() as $p):?><option value="<?= (int)$p['id'] ?>"><?= sanitize($p['reference'].' · '.$p['total_amount'].' '.$p['currency_code']) ?></option><?php endforeach ?></select></label><label><?= __t('Verified historical amount paid','مبلغ تاریخیِ پرداخت‌شده و تأییدشده','تایید شوې تاریخي تادیه') ?><input class="form-control" name="verified_paid" type="number" min="0" step="0.01" required></label><label><?= __t('Review reference','مرجع بررسی','د بیاکتنې مرجع') ?><textarea class="form-control" name="review_note" minlength="10" maxlength="1000" required></textarea></label><label><input type="checkbox" name="inventory_opening_verified" value="1" required> <?= __t('I reviewed inventory openings separately and verified this supplier balance.','ماندهٔ آغاز موجودی را جدا بررسی و حساب عرضه‌کننده را تطبیق کرده‌ام.','لومړنۍ موجودي او د عرضه کوونکي مانده مې جلا تایید کړې.') ?></label><button class="btn btn-primary"><?= __t('Approve legacy opening','تأیید ماندهٔ آغاز قدیمی','پخوانۍ لومړنۍ مانده تایید') ?></button></form></details></section>
<section class="card modern-form"><details><summary><?= __t('Post manual / opening journal','ثبت سند دستی یا ماندهٔ آغاز','لاسي یا لومړنی سند') ?></summary><form method="post"><?= csrf_field() ?><input name="action" type="hidden" value="approve_journal"><input name="request_key" type="hidden" value="<?= bin2hex(random_bytes(16)) ?>"><div class="form-grid"><label><?= __t('Date','تاریخ','نېټه') ?><input class="form-control" type="date" name="posting_date" value="<?= date('Y-m-d') ?>" required></label><label><?= __t('Currency','ارز','اسعار') ?><?= currency_select('currency_code') ?></label><label><?= __t('Description','شرح سند','تشریح') ?><input class="form-control" name="description" minlength="3" maxlength="1000" required></label></div><?php for($i=0;$i<8;$i++):?><div class="form-grid"><label><?= __t('Account','حساب','حساب') ?><select class="form-control" name="lines[<?= $i ?>][code]"><?php foreach($balances as $a):?><option value="<?= sanitize($a['code']) ?>"><?= sanitize($a['code'].' · '.account_label($a)) ?></option><?php endforeach ?></select></label><label><?= __t('Debit','بدهکار','ډېبېټ') ?><input class="form-control" type="number" min="0" step="0.01" name="lines[<?= $i ?>][debit]" value="0"></label><label><?= __t('Credit','بستانکار','کرېډېټ') ?><input class="form-control" type="number" min="0" step="0.01" name="lines[<?= $i ?>][credit]" value="0"></label></div><?php endfor ?><button class="btn btn-primary"><?= __t('Approve balanced journal','تأیید سند تراز','متوازن سند تایید') ?></button></form></details></section>
